struct WallTableState {
  double yPlus=0,uPlus=0,kPlus=0,omegaPlus=0,nutPlus=0,pkPlus=0,uTau=0;
  bool ok=false;
};

__device__ __forceinline__ int lower_logy(double ly){
  int lo=0,hi=SST_TABLE_N-1;
  while(hi-lo>1){int m=(lo+hi)>>1;if(SST_LOGY[m]<=ly)lo=m;else hi=m;}
  return lo;
}
__device__ __forceinline__ double lerp(double a,double b,double t){return a+t*(b-a);}
__device__ __forceinline__ WallTableState lookup_yplus(double yp){
  WallTableState q;
  if(!(yp>0.0)||!isfinite(yp))return q;
  const double ymin=exp(SST_LOGY[0]),ymax=exp(SST_LOGY[SST_TABLE_N-1]);
  if(yp<ymin){
    q.yPlus=yp;q.uPlus=yp;
    const double r=yp/ymin;
    q.kPlus=SST_KPLUS[0]*r*r;
    q.omegaPlus=6.0/(0.075*yp*yp);
    q.nutPlus=0.0;q.pkPlus=0.0;q.ok=true;return q;
  }
  if(yp>ymax)yp=ymax;
  const double ly=log(yp);int i=lower_logy(ly);if(i>SST_TABLE_N-2)i=SST_TABLE_N-2;
  const double d=SST_LOGY[i+1]-SST_LOGY[i];const double t=d>0?(ly-SST_LOGY[i])/d:0.0;
  q.yPlus=yp;q.uPlus=lerp(SST_UPLUS[i],SST_UPLUS[i+1],t);
  q.kPlus=lerp(SST_KPLUS[i],SST_KPLUS[i+1],t);
  q.omegaPlus=lerp(SST_OMEGAPLUS[i],SST_OMEGAPLUS[i+1],t);
  q.nutPlus=lerp(SST_NUTPLUS[i],SST_NUTPLUS[i+1],t);
  q.pkPlus=lerp(SST_PKPLUS[i],SST_PKPLUS[i+1],t);q.ok=true;return q;
}
__device__ __forceinline__ WallTableState invert_velocity(double Ut,double yd,double nu){
  WallTableState q;
  if(!(Ut>=0.0&&yd>0.0&&nu>0.0)||!isfinite(Ut)||!isfinite(yd)||!isfinite(nu))return q;
  const double Re=Ut*yd/nu;
  if(Re<=0.0){q=lookup_yplus(1e-12);q.uTau=0.0;return q;}
  const double Rmin=exp(SST_LOGR[0]),Rmax=exp(SST_LOGR[SST_TABLE_N-1]);
  double yp=0.0;
  if(Re<Rmin)yp=sqrt(Re); // U+=y+ in the viscous limit, so Re=y+^2.
  else if(Re>Rmax)return q; // fail loudly rather than silently extrapolate beyond the table.
  else{
    const double lr=log(Re);int lo=0,hi=SST_TABLE_N-1;
    while(hi-lo>1){int m=(lo+hi)>>1;if(SST_LOGR[m]<=lr)lo=m;else hi=m;}
    const double d=SST_LOGR[hi]-SST_LOGR[lo];const double t=d>0?(lr-SST_LOGR[lo])/d:0.0;
    yp=exp(lerp(SST_LOGY[lo],SST_LOGY[hi],t));
  }
  q=lookup_yplus(yp);if(!q.ok)return q;q.uTau=nu*yp/yd;q.ok=isfinite(q.uTau)&&q.uTau>=0.0;return q;
}
